const u = $('Telegram Trigger').first().json;
const profil = $input.first().json || {};
const cb = u.callback_query;
const msg = u.message || (cb && cb.message) || {};
const chatId = String((msg.chat && msg.chat.id) || '');
const text = String((u.message && u.message.text) || '').trim();
if (!chatId) return [];
if (profil.chat_id && String(profil.chat_id) !== chatId) return [];

let aktion = 'chat';
let param = '';
const lower = text.toLowerCase();
const rest = text.includes(' ') ? text.slice(text.indexOf(' ') + 1).trim() : '';
if (cb) {
  const teile = String(cb.data || '').split(':');
  const art = teile.shift();
  param = teile.join(':');
  if (art === 'cook') aktion = 'kochen';
  else if (art === 'inv') aktion = 'inventar_aktion';
  else if (art === 'bon') aktion = 'bon_antwort';
  else if (art === 'cmd' && param === 'rezepte') aktion = 'rezepte';
  else aktion = 'hilfe';
} else if (lower.startsWith('/start')) aktion = 'start';
else if (lower.startsWith('/rezepte')) { aktion = 'rezepte'; param = rest; }
else if (lower.startsWith('/wochenplan')) { aktion = 'wochenplan'; param = rest; }
else if (lower.startsWith('/inventar') || lower.startsWith('/vorrat')) aktion = 'inventar';
else if (lower.startsWith('/hilfe') || lower.startsWith('/help')) aktion = 'hilfe';
else if (!text) aktion = 'hilfe';

return [{ json: { aktion, param, chat_id: chatId, text, callback_id: cb ? String(cb.id) : '' } }];

const ctx = $('Update auswerten').first().json;
const rezept = $('Rezept laden').first().json || {};
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
if (!rezept.id) return [{ json: { product_id: 0, rezept_id: 0, chat_id: ctx.chat_id, text: 'Dieses Rezept finde ich nicht mehr 🤔' } }];
if (rezept.status === 'gekocht') return [{ json: { product_id: 0, rezept_id: rezept.id, chat_id: ctx.chat_id, text: '„' + esc(rezept.titel) + '“ ist schon als gekocht gebucht ✅' } }];

const klein = x => String(x || '').trim().toLowerCase();
const quCode = {};
for (const i of $('Grocy-Einheiten laden').all()) { const q = i.json; if (q && q.id) quCode[q.id] = klein(q.name) === 'gramm' ? 'g' : klein(q.name) === 'milliliter' ? 'ml' : klein(q.name) === 'stück' ? 'stk' : klein(q.name); }
const inv = {};
for (const i of $('Grocy-Bestand laden (Kochen)').all()) {
  const r = i.json;
  if (r && r.product_id) inv[r.product_id] = { id: Number(r.product_id), name: (r.product || {}).name, menge: Number(r.amount) || 0, einheit: quCode[(r.product || {}).qu_id_stock] || 'stk' };
}
let zutaten = [];
try { zutaten = JSON.parse(rezept.zutaten_json || '[]'); } catch (e) { zutaten = []; }

const gruppen = { g: ['g', 1], kg: ['g', 1000], ml: ['ml', 1], l: ['ml', 1000] };
const umrechnen = (menge, von, nach) => {
  von = String(von || '').toLowerCase(); nach = String(nach || '').toLowerCase();
  if (von === nach) return menge;
  const a = gruppen[von], b = gruppen[nach];
  if (a && b && a[0] === b[0]) return menge * a[1] / b[1];
  return null;
};

const abbuchung = {};
const probleme = [];
// Ist-Verbrauch: Anteil jeder Zutat, der nicht aus dem Vorrat abgebucht wird (fehlt, Einheit passt nicht, nur teilweise da)
const rest = [];
const restEintrag = (z, anteil) => { if (anteil > 0.01) rest.push({ z, anteil }); };
for (const z of zutaten) {
  const pid = z.product_id != null ? z.product_id : z.inventar_id;
  if (pid == null) { restEintrag(z, 1); continue; }
  const v = inv[pid];
  if (!v || v.menge <= 0) { probleme.push(esc(z.name) + ' (nicht mehr im Bestand)'); restEintrag(z, 1); continue; }
  const abzug = umrechnen(Number(z.menge) || 0, z.einheit, v.einheit);
  if (abzug === null) { probleme.push(esc(z.name) + ' (Einheit passt nicht)'); restEintrag(z, 1); continue; }
  let menge = Math.min(v.menge, Math.round(abzug * 100) / 100);
  if (abzug > 0 && menge < abzug) restEintrag(z, 1 - menge / abzug);
  if (v.einheit === 'stk' && v.menge - menge < 0.25) menge = v.menge;
  if (menge <= 0) continue;
  v.menge = Math.round((v.menge - menge) * 100) / 100;
  abbuchung[v.id] = { product_id: v.id, amount: Math.round(((abbuchung[v.id] ? abbuchung[v.id].amount : 0) + menge) * 100) / 100, name: v.name, rest: v.menge, einheit: v.einheit };
}
const zeilen = Object.values(abbuchung).map(u => '• ' + esc(u.name) + ': −' + u.amount + ' ' + esc(u.einheit) + (u.rest <= 0 ? ' (aufgebraucht)' : ', noch ' + u.rest + ' ' + esc(u.einheit)));
let text = '✅ <b>' + esc(rezept.titel) + '</b> als gekocht gebucht (' + (rezept.kcal || 0) + ' kcal · P ' + (rezept.protein_g || 0) + ' g)';
if (zeilen.length) text += '\n\n<b>In Grocy verbraucht</b>\n' + zeilen.join('\n');
if (probleme.length) text += '\n\n⚠️ Nicht aus dem Vorrat abgebucht: ' + probleme.join(', ') + '.';

// Nährwerte des Rests: je Zutat aus dem Rezept (pro 100 g), sonst anteilig aus den Rezeptwerten (geschätzt)
const r1 = x => Math.round(x * 10) / 10;
const gesamtGramm = zutaten.reduce((s, z) => s + (Number(z.gramm) || 0), 0);
const verzehr_rest = rest.map(({ z, anteil }) => {
  const gramm = (Number(z.gramm) || 0) * anteil;
  if (z.kcal_100 != null && gramm > 0) {
    const f = gramm / 100;
    return { name: z.name, gramm: r1(gramm), kcal: r1(z.kcal_100 * f), protein: r1((z.p_100 || 0) * f), fett: r1((z.f_100 || 0) * f), kh: r1((z.kh_100 || 0) * f), geschaetzt: false };
  }
  const teil = gesamtGramm > 0 ? gramm / gesamtGramm : anteil / Math.max(1, zutaten.length);
  return { name: z.name, gramm: gramm > 0 ? r1(gramm) : null, kcal: r1((rezept.kcal || 0) * teil), protein: r1((rezept.protein_g || 0) * teil),
    fett: r1((rezept.fett_g || 0) * teil), kh: r1((rezept.kh_g || 0) * teil), geschaetzt: true };
}).filter(e => e.kcal > 0 || e.gramm > 0);
if (verzehr_rest.length) text += '\n📊 ' + verzehr_rest.length + ' Zutat' + (verzehr_rest.length === 1 ? '' : 'en') + ' ohne Vorrat im Verzehr-Protokoll erfasst.';

const list = Object.values(abbuchung);
if (!list.length) return [{ json: { product_id: 0, rezept_id: rezept.id, chat_id: ctx.chat_id, text, verzehr_rest } }];
return list.map(u => ({ json: { product_id: u.product_id, amount: u.amount, rezept_id: rezept.id, chat_id: ctx.chat_id, text, verzehr_rest } }));

const ctx = $('Update auswerten').first().json;
const teile = String(ctx.param).split(':');
const pid = teile[0];
const aktion = teile[1] || '';
const details = $('Produktdetails laden').first().json || {};
const entries = $('Bestandseinträge laden').all().map(i => i.json).filter(e => e && e.id);
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const name = esc((details.product && details.product.name) || 'Produkt');
const menge = Number(details.stock_amount) || 0;
const heute = DateTime.now().setZone('Europe/Berlin').startOf('day');
if (menge <= 0) return [{ json: { method: 'NONE', chat_id: ctx.chat_id, text: name + ' ist schon nicht mehr im Bestand 👍' } }];
if (aktion === 'verbraucht' || aktion === 'weg') {
  const text = aktion === 'weg' ? '🗑️ ' + name + ' als weggeworfen gebucht. Nächstes Mal schaffen wir das! 💪' : '🍽️ ' + name + ' als verbraucht gebucht.';
  return [{ json: { method: 'POST', pfad: '/api/stock/products/' + pid + '/consume', body: { amount: menge, spoiled: aktion === 'weg', transaction_type: 'consume' }, chat_id: ctx.chat_id, text } }];
}
const neu = heute.plus({ days: 3 }).toISODate();
const text = '👍 ' + name + ' bleibt im Vorrat, neue Erinnerung ab ' + heute.plus({ days: 3 }).setLocale('de').toFormat('ccc dd.LL.') + '.';
const faellig = entries.filter(e => String(e.best_before_date || '') < neu);
if (!faellig.length) return [{ json: { method: 'NONE', chat_id: ctx.chat_id, text } }];
return faellig.map(e => ({ json: { method: 'PUT', pfad: '/api/stock/entry/' + e.id, body: { amount: e.amount, best_before_date: neu, location_id: e.location_id, purchased_date: e.purchased_date, price: e.price, open: e.open }, chat_id: ctx.chat_id, text } }));

const ctx = $('Update auswerten').first().json;
const zone = 'Europe/Berlin';
const heute = DateTime.now().setZone(zone).startOf('day');
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const orteMap = {};
for (const i of $('Grocy-Lagerorte laden').all()) if (i.json && i.json.id) orteMap[i.json.id] = i.json.name;
const qu = {};
for (const i of $('Grocy-Einheiten laden (Liste)').all()) if (i.json && i.json.id) qu[i.json.id] = i.json.name;
const rows = $('Grocy-Bestand laden (Liste)').all().map(i => i.json).filter(r => r && r.product_id && Number(r.amount) > 0);
if (!rows.length) return [{ json: { chat_id: ctx.chat_id, text: '📦 Dein Grocy-Bestand ist leer. Sobald ein REWE-eBon kommt, fülle ich ihn auf.' } }];
const orte = {};
for (const r of rows) {
  const p = r.product || {};
  const bbd = String(r.best_before_date || '');
  r.tage = bbd && !bbd.startsWith('2999') ? Math.round(DateTime.fromISO(bbd.slice(0, 10), { zone }).diff(heute, 'days').days) : 9999;
  const ort = orteMap[p.location_id] || 'Sonstiges';
  (orte[ort] = orte[ort] || []).push(r);
}
const badge = t => t < 0 ? '🔴 abgelaufen' : t === 0 ? '🔴 heute' : t <= 2 ? '🟠 ' + t + ' T.' : t <= 6 ? '🟡 ' + t + ' T.' : t >= 9999 ? '' : '🟢 ' + t + ' T.';
let text = '📦 <b>Dein Vorrat in Grocy</b> (' + rows.length + ' Produkte)\n';
for (const ort of Object.keys(orte).sort()) {
  text += '\n<b>' + esc(ort) + '</b>\n' + orte[ort].sort((a, b) => a.tage - b.tage).map(r => '• ' + esc((r.product || {}).name) + ' – ' + (Math.round(Number(r.amount) * 10) / 10) + ' ' + esc(qu[(r.product || {}).qu_id_stock] || '') + ' ' + badge(r.tage)).join('\n') + '\n';
}
return [{ json: { chat_id: ctx.chat_id, text: text.slice(0, 4000) } }];

let s = String($input.first().json.output || '');
if (s.includes('</think>')) s = s.split('</think>').pop();
s = s.trim().replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
s = s.replace(/\*\*(.+?)\*\*/g, '<b>$1</b>').replace(/^#+\s*(.+)$/gm, '<b>$1</b>');
return [{ json: { chat_id: $('Update auswerten').first().json.chat_id, text: (s || 'Hm, dazu fällt mir gerade nichts ein 🤔').slice(0, 4000) } }];

const ctx = $('Update auswerten').first().json;
const t = String(ctx.param || '').split(':');
const grocy_id = Number(t[2]) || 0;
const r = $input.first().json || {};
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const p = r.produkt;
let text;
if (!r.ok) text = '⚠️ Konnte die Antwort nicht speichern: ' + esc(r.fehler || r.detail || 'REWE-Dienst nicht erreichbar');
else if (!p) text = '👌 Okay, „' + esc(r.bon_text) + '“ bleibt wie eingebucht.';
else text = '✅ Gemerkt: „' + esc(r.bon_text) + '“ = <b>' + esc(p.name) + '</b>' + (p.brand ? ' (' + esc(p.brand) + ')' : '')
  + (grocy_id ? '\nIn Grocy umbenannt' + (p.ean ? ', Barcode gespeichert' : '') + (p.kcal_100 != null ? ', REWE-Nährwerte übernommen' : '') + '.' : '')
  + '\nBeim nächsten Bon erkenne ich es automatisch.';
const preis = p && p.price != null ? Number(p.price).toFixed(2).replace('.', ',') + ' €' : '';
return [{ json: { chat_id: ctx.chat_id, text, grocy_id, gewaehlt: !!(r.ok && p && grocy_id), produkt: p || {},
  beschreibung: p ? ['REWE', p.brand, preis, 'REWE-ID ' + p.rewe_product_id, p.ean ? 'EAN ' + p.ean : ''].filter(Boolean).join(' · ') : '' } }];
